SCRIPT = r"""
<script>
(() => {
  const state={data:null,auth:false,filter:'',platform:'',status:'',backend:'',limit:120};
  const fmtTime=value=>{if(!value)return '尚無紀錄';const d=typeof value==='number'?new Date(value*1000):new Date(value);return isNaN(d)?'尚無紀錄':new Intl.DateTimeFormat('zh-TW',{dateStyle:'short',timeStyle:'short',timeZone:'Asia/Taipei'}).format(d)};
  const fmtInterval=h=>{if(h==null)return '累積中';if(h<48)return `${h.toFixed(Number.isInteger(h)?0:h<10?1:0)} 小時`;return `${(h/24).toFixed(h<96?1:0)} 天`};
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const chip=(label,count,value,kind)=>`<button class="fchip" data-${kind}-filter="${esc(value)}" aria-pressed="${value===''?'true':'false'}"><span class="fchip-label">${label}</span><span class="fchip-count">${Number(count).toLocaleString()}</span></button>`;
  function renderSummary(){const d=state.data,c=d.counts,a=d.apify||{},usage=d.apiUsage||{};document.querySelector('#status-totals').innerHTML=[['監測來源',c.sources],['正常',c.fresh],['等待排程',c.due],['額度受限',c.blocked],['錯誤',c.errors]].map(([label,value])=>`<article class="status-total"><span>${label}</span><strong>${Number(value).toLocaleString()}</strong></article>`).join('');document.querySelector('#status-filters').innerHTML=chip('全部',c.sources,'','status')+chip('正常',c.fresh,'ok','status')+chip('等待排程',c.due,'due','status')+chip('額度受限',c.blocked,'blocked','status')+chip('錯誤',c.errors,'error','status');const platforms=['Instagram','Facebook','Threads','X','校園公告'];document.querySelector('#platform-filters').innerHTML=chip('全部',c.sources,'','platform')+platforms.map(name=>chip(name,d.sources.filter(s=>s.platform===name).length,name,'platform')).join('');const used=Number(a.usedUsd||0),limit=Number(a.limitUsd||0),remaining=Number(a.remainingUsd||0),percent=limit?Math.min(100,used/limit*100):0,accountRows=(a.accounts||[]).map(row=>`<div class="status-apify-account"><strong>${esc(row.label)}</strong><span class="${row.available&&!row.exhausted?'is-ok':'is-bad'}">${row.available?(row.exhausted?'已用完':'可使用'):'無法取得'}</span><span>剩餘 US$${Number(row.remainingUsd||0).toFixed(3)} ／ ${Number(row.limitUsd||0).toFixed(2)}</span><span class="status-apify-reset">重置 ${fmtTime(row.cycleEnd)}</span></div>`).join('');document.querySelector('#apify-quota').classList.toggle('is-exhausted',!!a.exhausted);document.querySelector('#apify-quota').innerHTML=`<div class="status-apify-main"><h3>Apify API 額度</h3><strong>US$${remaining.toFixed(3)}</strong><span>${a.available===false?'目前無法取得額度':a.exhausted?'所有帳號額度皆不可用':`${Number(a.usableAccountCount||0)} / ${Number(a.accountCount||0)} 個帳號可使用`}${a.stale?'（含快取資料）':''}</span><div class="status-quota-bar" aria-label="Apify 額度已使用 ${percent.toFixed(0)}%"><i style="width:${percent}%"></i></div></div><div class="status-apify-stat"><span>已用／總上限</span><strong>US$${used.toFixed(3)} / ${limit.toFixed(2)}</strong></div><div class="status-apify-stat"><span>最晚重置時間</span><strong>${fmtTime(a.cycleEnd)}</strong></div><div class="status-apify-stat"><span>執行中／資料時間</span><strong>${Number(a.activeActorJobs||0)} 個 Actor</strong><span>${fmtTime(a.checkedAt)}</span></div>${accountRows?`<div class="status-apify-accounts"><h4>API 帳號狀態</h4>${accountRows}</div>`:''}`;const info={'RSSHub → Instaloader':['Instagram 貼文','RSSHub，失敗時切換 Instaloader','RSSHub'],'Instaloader':['Instagram 限時動態','Instaloader 批次 · 共用 RSSHub 登入','Instaloader'],'Apify':['Facebook 粉專貼文','Apify 帳號池 · 批次 Actor API','Apify'],'RSSHub':['Threads／X 公開貼文','本機 RSSHub','RSSHub'],'NTHU RPage':['清大 RPage 公告','網頁爬蟲',null],'NYCU InfoNews':['陽明交大公告','網頁爬蟲',null],'WordPress API':['藝文中心公告','WordPress REST API',null],'JSON API':['NYCU LIFE 活動','JSON API',null]};document.querySelector('#method-cards').innerHTML=(d.methods||[]).map(m=>{const meta=info[m.backend]||[m.backend,m.backend,null],u=meta[2]&&usage[meta[2]],api=u?`<div class="status-method-api">${meta[2]} 24h：${u.requests24h} 次 · ${u.errors24h} 錯誤</div>`:'';return `<button class="status-method-card" data-backend-filter="${esc(m.backend)}" aria-pressed="false"><div class="status-method-title"><strong>${esc(meta[0])}</strong><span>${esc(meta[1])}</span></div><div class="status-method-count"><b>${Number(m.sources).toLocaleString()}</b><span>個排程來源</span></div><div class="status-method-meta">目標每 ${fmtInterval(m.targetIntervalHours)} · 正常 ${m.fresh} · 待抓 ${m.due} · 受限 ${m.blocked} · 錯誤 ${m.errors}${api}</div></button>`}).join('');document.querySelector('#pipeline-note').textContent=`主 pipeline 每 ${fmtInterval(d.pipeline?.intervalHours)}啟動；各卡片顯示的是每個來源真正的最短重抓間隔。點卡片可篩選下方列表。`;}
  function renderRows(){const q=state.filter.toLowerCase();const rank={error:0,blocked:1,due:2,ok:3};const rows=state.data.sources.filter(s=>(!q||`${s.name} ${s.username} ${s.backend} ${s.kindLabel||''}`.toLowerCase().includes(q))&&(!state.platform||s.platform===state.platform)&&(!state.status||s.status===state.status)&&(!state.backend||s.backend===state.backend)).sort((a,b)=>(rank[a.status]-rank[b.status])||((a.nextDue||0)-(b.nextDue||0))||a.name.localeCompare(b.name,'zh-Hant'));const visible=rows.slice(0,state.limit);document.querySelector('#source-count').textContent=`顯示 ${visible.length.toLocaleString()} / ${rows.length.toLocaleString()} 筆${state.backend?` · ${state.backend}`:''}`;
    const items=visible.map(s=>`<div class="status-src-row"><div class="status-row-name"><div class="status-name">${esc(s.name)}</div><div class="status-sub">${esc(s.platform)} ${esc(s.kindLabel||'')} · ${esc(s.username)}</div></div><div class="status-backend">${esc(s.backend)}</div><div class="status-row-status"><span class="status-chip ${s.status}">${s.status==='ok'?'正常':s.status==='due'?'等待排程':s.status==='blocked'?'額度受限':'錯誤'}</span>${s.lastError?`<details class="status-error-details"><summary>查看詳情</summary><div>${esc(s.lastError)}</div></details>`:''}</div><div class="status-time status-recent"><div>嘗試 ${fmtTime(s.lastAttempt)}</div><div class="status-sub">成功 ${fmtTime(s.lastSuccess)}</div></div><div class="status-time status-next"><div>${fmtTime(s.nextDue)}</div><div class="status-sub">目標 ${fmtInterval(s.targetIntervalHours)} · 實際 ${fmtInterval(s.averageIntervalHours)}</div></div><button class="status-fetch" data-source-request="${esc(s.id)}" ${!state.auth||s.blockedReason?'disabled':''} title="${esc(!state.auth?'登入後可要求優先抓取':s.blockedReason||'加入優先抓取佇列')}">${s.blockedReason?'額度':'先抓'}</button></div>`).join('');const more=visible.length<rows.length?`<button class="filter-expand status-more" data-show-more>顯示更多（還有 ${(rows.length-visible.length).toLocaleString()} 筆）</button>`:'';document.querySelector('#source-rows').innerHTML=items+more||'<p class="status-count">沒有符合的來源。</p>';}
  async function requestFetch(id,button){button.disabled=true;const msg=document.querySelector('#status-message');msg.textContent='正在加入佇列…';try{const r=await fetch('/auth/fetch-requests',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({sourceId:id})});const p=await r.json();if(!r.ok)throw new Error(p.error||'要求失敗');msg.textContent=p.code==='duplicate'?'這個來源已在優先佇列中。':'已加入優先佇列，仍會遵守冷卻與 API 額度。';button.textContent='已排';}catch(e){msg.textContent=e.message;button.disabled=false;}}
  document.addEventListener('click',e=>{const request=e.target.closest('[data-source-request]');if(request){requestFetch(request.dataset.sourceRequest,request);return}if(e.target.closest('[data-show-more]')){state.limit+=120;renderRows();return}const method=e.target.closest('[data-backend-filter]');if(method){state.backend=state.backend===method.dataset.backendFilter?'':method.dataset.backendFilter;state.limit=120;document.querySelectorAll('[data-backend-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.backendFilter===state.backend)));renderRows();return}const status=e.target.closest('[data-status-filter]');if(status){state.status=status.dataset.statusFilter;state.limit=120;document.querySelectorAll('[data-status-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===status)));renderRows();return}const platform=e.target.closest('[data-platform-filter]');if(platform){state.platform=platform.dataset.platformFilter;state.limit=120;document.querySelectorAll('[data-platform-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===platform)));renderRows();}});document.querySelector('#source-search').addEventListener('input',e=>{state.filter=e.target.value;state.limit=120;renderRows()});
  Promise.all([fetch('/api/status.json',{cache:'no-store'}).then(r=>r.json()),fetch('/auth/me',{cache:'no-store'}).then(r=>r.ok?r.json():{authenticated:false}).catch(()=>({authenticated:false}))]).then(([data,me])=>{state.data=data;state.auth=!!me.authenticated;document.querySelector('#snapshot').textContent=`資料快照：${fmtTime(data.generatedAt)} · ${state.auth?'已登入，可要求優先抓取':'登入後可要求優先抓取'}`;renderSummary();renderRows()}).catch(e=>{document.querySelector('#status-message').textContent=`狀態資料讀取失敗：${e.message}`});
})();
</script>
"""


def build() -> dict:
    payload = build_status_payload()
    OUT_API.parent.mkdir(parents=True, exist_ok=True)
    OUT_PAGE.parent.mkdir(parents=True, exist_ok=True)
    OUT_API.write_text(json.dumps(payload, ensure_ascii=False, separators=(",", ":")), encoding="utf-8")
    content = f"""
<section class="status-page">
  <section class="hero"><h1>資料來源狀態</h1><p>查看竹梅每個公開帳號與公告來源的抓取排程。登入後可以要求某個來源優先抓取；系統仍會遵守 Instagram 冷卻與 Apify 額度。<span class="status-snapshot" id="snapshot">資料快照：載入中…</span></p></section>
  <section class="status-overview" aria-label="抓取系統總覽">
    <div class="status-section-head"><h2>系統總覽</h2><p>大數字是目前排程內的來源數</p></div>
    <div class="status-total-grid" id="status-totals"></div>
    <article class="status-apify" id="apify-quota" aria-label="Apify API 額度"></article>
    <div class="status-section-head"><h2>爬取方式</h2><p id="pipeline-note">讀取排程設定中…</p></div>
    <div class="status-method-grid" id="method-cards"></div>
  </section>
  <section class="filters" aria-label="來源狀態篩選">
    <div class="filter-row"><span class="label">狀態</span><span class="fgroup" id="status-filters"></span><label class="search-hit status-search"><span class="sr-only">搜尋來源</span><input id="source-search" type="search" placeholder="搜尋名稱、帳號或後端"></label></div>
    <div class="filter-row"><span class="label">平台</span><span class="fgroup" id="platform-filters"></span></div>
  </section>
  <p class="status-note">同一個 Instagram 帳號會分成「貼文」與「限時動態」兩列，因為抓法與頻率不同。「實際」需累積至少兩次成功紀錄；沒有新貼文仍算抓取成功。</p>
  <p id="source-count" class="status-count"></p><p id="status-message" class="status-message" role="status"></p>
  <div class="status-src-table"><div class="status-src-head"><span>來源／內容</span><span>爬取方式</span><span>狀態</span><span>最近抓取</span><span>下次／頻率</span><span>優先</span></div><div id="source-rows"></div></div>
</section>{STYLE}{SCRIPT}
"""
    OUT_PAGE.write_text(page_shell("資料來源狀態｜竹梅活動觀測站", "竹梅各公開來源最後與下次爬取時間、實際頻率和 API 使用量。", content, canonical="https://chumei.observe.tw/status/"), encoding="utf-8")
    return payload


if __name__ == "__main__":
    result = build()
    print(f"status: {result['counts']['sources']} sources, {result['counts']['errors']} errors")
